 }

-Promise.all(loadPromises).then(() => {
-  resolve(
-    tabmail.tabInfo.map(tab => {
-      const data = { mode: tab.mode.name };
-      if (tab.browser) {
-        data.url = tab.browser.currentURI?.spec;
-      }
-      if (tab.mode.name == "contentTab") {
-        // How we handle clicks on links in this tab.
